	int maximumOutstandingTaskCount() {
		return workerLimit + queuedTaskLimit;
	}

	boolean isWorkerThread() {
		return CURRENT_SCHEDULER.get() == this;
	}

	<T> Future<T> submit(ResourceLease lease, Callable<T> operation) {
		return schedule(lease, operation);
	}

	<T> Future<T> submit(ResourceLease lease, Callable<T> operation, Runnable whenFinished) {
		return schedule(lease, operation, true, whenFinished);
	}

	<T> Future<T> trySubmit(ResourceLease lease, Callable<T> operation) {
		return schedule(lease, operation, false);
	}

	/**
	 * Executes a child task inline when called from one of this scheduler's workers. This avoids waiting in a worker
	 * for a child queued behind the current task.
	 */
	<T> Future<T> submitOrRunInline(ResourceLease lease, Callable<T> operation) {
		return schedule(lease, operation);
	}

	<T> Future<T> submitOrRunInline(ResourceLease lease, Callable<T> operation, Runnable whenFinished) {
		return schedule(lease, operation, true, whenFinished);
	}

	<T> List<T> runOrdered(List<Work<T>> work) throws IOException {
		if (CURRENT_SCHEDULER.get() == this) {
			throw new IllegalStateException("ordered bulk work must be coordinated outside the scheduler pool");
		}
		List<Work<T>> orderedWork = List.copyOf(work);
		Object[] results = new Object[orderedWork.size()];
		int next = 0;
		int batchLimit = workerLimit + queuedTaskLimit;
		while (next < orderedWork.size()) {
			List<Future<T>> batch = new ArrayList<>(Math.min(batchLimit, orderedWork.size() - next));
			int first = next;
			try {
				while (next < orderedWork.size() && batch.size() < batchLimit) {
					Work<T> item = orderedWork.get(next);
					ResourceLease lease = reserveForWork(item);
					batch.add(submit(lease, item.operation()));
					next++;
				}
				for (int i = 0; i < batch.size(); i++) {
					results[first + i] = batch.get(i).get();
				}
			} catch (InterruptedException e) {
				cancelBatch(batch);
				awaitTasksUninterruptibly();
				Thread.currentThread().interrupt();
				InterruptedIOException interrupted = new InterruptedIOException("interrupted while joining bulk tasks");
				interrupted.initCause(e);
				throw interrupted;
			} catch (ExecutionException | CancellationException | RejectedExecutionException e) {
				cancelBatch(batch);
				Throwable failure = firstFailure();
				awaitTasksUninterruptibly();
				if (failure == null && e instanceof ExecutionException executionException) {
					failure = executionException.getCause();
				}
				if (failure == null) {
					failure = e;
				}
				if (failure instanceof IOException ioException) {
					throw ioException;
				}
				throw new IOException("bulk task failed", failure);
			} catch (IOException e) {
				cancelBatch(batch);
				awaitTasksUninterruptibly();
				throw e;
			}
		}
		List<T> orderedResults = new ArrayList<>(results.length);
		for (Object result : results) {
			@SuppressWarnings("unchecked")
			T value = (T) result;
			orderedResults.add(value);
		}
		return orderedResults;
	}

	private <T> TrackedTask<T> schedule(ResourceLease lease, Callable<T> operation) {
		return schedule(lease, operation, true, () -> {
		});
	}

	private <T> TrackedTask<T> schedule(ResourceLease lease, Callable<T> operation, boolean waitForQueue) {
		return schedule(lease, operation, waitForQueue, () -> {
		});
	}

	private <T> TrackedTask<T> schedule(ResourceLease lease, Callable<T> operation, boolean waitForQueue,
			Runnable whenFinished) {
		return schedule(lease, operation, waitForQueue, whenFinished, new AtomicBoolean());
	}

	private <T> TrackedTask<T> schedule(ResourceLease lease, Callable<T> operation, boolean waitForQueue,
			Runnable whenFinished, AtomicBoolean retainLeaseUntilConsumed) {
		if (lease == null || operation == null) {
			throw new NullPointerException("lease and operation are required");
		}
		Objects.requireNonNull(whenFinished, "whenFinished");
		if (lease.owner != this) {
			throw new IllegalArgumentException("resource lease belongs to another scheduler");
		}
		lease.ensureOpen();
		boolean inline = CURRENT_SCHEDULER.get() == this;
		TrackedTask<T> task;
		synchronized (stateLock) {
			while (!inline && queuedTasks.get() >= queuedTaskLimit && accepting && firstFailure == null) {
				if (!waitForQueue) {
					return null;
				}
				try {
					stateLock.wait();
				} catch (InterruptedException e) {
					lease.close();
					Thread.currentThread().interrupt();
					throw new RejectedExecutionException("interrupted while waiting for bulk task queue capacity", e);
				}
			}
			if (!accepting || firstFailure != null) {
				lease.close();
				throw rejected("scheduler is stopping", firstFailure);
			}
			lease.ensureOpen();
			lease.transferToTask();
			task = new TrackedTask<>(lease, operation, whenFinished, retainLeaseUntilConsumed);
			tasks.add(task);
			if (!inline) {
				task.markQueued();
			}
		}
		if (inline) {
			task.run();
		} else {
			try {
				executor.execute(task);
			} catch (RejectedExecutionException e) {
				task.cancel(false);
				throw e;
			}
		}
		return task;
	}

	private ResourceLease reserveForWork(Work<?> work) throws IOException {
		boolean memoryFloor = work.memoryBytes() > memoryLimitBytes;
		if (memoryFloor && !work.allowSerialMemoryFloor() || work.fileDescriptors() > fileDescriptorLimit) {
			throw new IOException("bulk task reservation exceeds configured memory or file-descriptor limit");
		}
		synchronized (stateLock) {
			while (true) {
				if (!accepting || firstFailure != null) {
					throw new IOException("bulk task scheduler is stopping", firstFailure);
				}
				ResourceLease lease;
				if (memoryFloor) {
					lease = reserveExclusiveMemoryFloor(work.memoryBytes(), work.fileDescriptors());
				} else {
					lease = tryReserve(work.memoryBytes(), work.fileDescriptors());
				}
				if (lease != null) {
					return lease;
				}
				if (CURRENT_SCHEDULER.get() == this) {
					throw new IOException("bulk worker cannot wait for resources held by scheduler tasks");
				}
				if (tasks.isEmpty() && exclusiveFloorLease == null) {
					if (work.allowSerialMemoryFloor()
							&& work.memoryBytes() <= memoryLimitBytes
							&& Math.addExact(reservedMemoryBytes, work.memoryBytes()) > memoryLimitBytes) {
						lease = reserveExclusiveMemoryFloor(work.memoryBytes(), work.fileDescriptors());
						if (lease != null) {
							return lease;
						}
					}
					throw new IOException(memoryFloor
							? "minimum-memory merge floor is blocked by resource leases held outside the scheduler"
							: "bulk task resources are held outside the scheduler");
				}
				try {
					stateLock.wait();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					InterruptedIOException interrupted = new InterruptedIOException(
							"interrupted while reserving bulk task resources");
					interrupted.initCause(e);
					throw interrupted;
				}
			}
		}
	}

	/** Reserves the delta from an already-counted coordinator-owned cursor lease. */
	private ResourceLease tryReserveAdaptiveBase(ResourceLease baseLease, long totalMemoryBytes,
			int totalFileDescriptors) throws IOException {
		validateAdaptiveBaseEnvelope(baseLease, totalMemoryBytes, totalFileDescriptors);
		synchronized (stateLock) {
			return tryReserveAdaptiveBaseLocked(baseLease, totalMemoryBytes, totalFileDescriptors);
		}
	}

	private ResourceLease tryReserveAdaptiveBaseLocked(ResourceLease baseLease, long totalMemoryBytes,
			int totalFileDescriptors) throws IOException {
		if ((baseLease.state.get() != 0 && baseLease.state.get() != 3) || !resourceLeases.contains(baseLease)) {
			throw new IOException("adaptive cursor base lease is no longer coordinator-owned");
		}
		boolean declaredExclusiveBase = exclusiveFloorLease == baseLease && baseLease.exclusiveFloor;
		if (!accepting || firstFailure != null || exclusiveFloorLease != null && !declaredExclusiveBase) {
			return null;
		}
		long additionalMemory = totalMemoryBytes - baseLease.accountedMemoryBytes;
		int additionalFileDescriptors = totalFileDescriptors - baseLease.accountedFileDescriptors;
		if (additionalMemory < 0 || additionalFileDescriptors < 0) {
			throw new IOException("adaptive resource envelope is smaller than its accounted cursor lease");
		}
		if (additionalFileDescriptors > fileDescriptorLimit - reservedFileDescriptors
				|| !declaredExclusiveBase && additionalMemory > memoryLimitBytes - reservedMemoryBytes) {
			return null;
		}
		reservedMemoryBytes += additionalMemory;
		reservedFileDescriptors += additionalFileDescriptors;
		peakReservedMemoryBytes.accumulateAndGet(reservedMemoryBytes, Math::max);
		peakReservedFileDescriptors.accumulateAndGet(reservedFileDescriptors, Math::max);
		ResourceLease lease = new ResourceLease(this, totalMemoryBytes, totalFileDescriptors, additionalMemory,
				additionalFileDescriptors, baseLease.bindingContext, false);
		resourceLeases.add(lease);
		return lease;
	}

	private void validateAdaptiveBaseEnvelope(ResourceLease baseLease, long totalMemoryBytes,
			int totalFileDescriptors) throws IOException {
		if (baseLease.owner != this) {
			throw new IOException("adaptive cursor base lease belongs to another scheduler");
		}
		if (totalMemoryBytes < baseLease.memoryBytes || totalFileDescriptors < baseLease.fileDescriptors) {
			throw new IOException("adaptive resource envelope is smaller than its declared cursor base lease");
		}
		if (totalFileDescriptors > fileDescriptorLimit) {
			throw new IOException("adaptive resource envelope exceeds the configured file-descriptor limit");
		}
	}

	private ResourceLease reserveAdaptiveBaseBlocking(ResourceLease baseLease, long totalMemoryBytes,
			int totalFileDescriptors, boolean allowSerialMemoryFloor) throws IOException {
		validateAdaptiveBaseEnvelope(baseLease, totalMemoryBytes, totalFileDescriptors);
		if (totalMemoryBytes > memoryLimitBytes) {
			if (!allowSerialMemoryFloor) {
				throw new IOException("bulk task reservation exceeds configured memory or file-descriptor limit");
			}
			return reserveExclusiveMemoryFloor(baseLease, totalMemoryBytes, totalFileDescriptors);
		}
		synchronized (stateLock) {
			while (true) {
				if (!accepting || firstFailure != null) {
					throw new IOException("bulk task scheduler is stopping", firstFailure);
				}
				ResourceLease lease = tryReserveAdaptiveBaseLocked(baseLease, totalMemoryBytes, totalFileDescriptors);
				if (lease != null) {
					return lease;
				}
				if (CURRENT_SCHEDULER.get() == this) {
					throw new IOException("bulk worker cannot wait for resources held by scheduler tasks");
				}
				if (tasks.isEmpty() && exclusiveFloorLease == null) {
					throw new IOException(
							"adaptive cursor base lease is blocked by resource leases held outside the scheduler");
				}
				try {
					stateLock.wait();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					InterruptedIOException interrupted = new InterruptedIOException(
							"interrupted while reserving adaptive bulk task resources");
					interrupted.initCause(e);
					throw interrupted;
				}
			}
		}
	}

	/**
	 * Admits one irreducible operation that cannot fit alongside already allocated coordinator-owned producer storage.
	 * The producer allocations remain charged to the effective minimum; no task may overlap this operation.
	 */
	private ResourceLease reserveExclusiveMemoryFloor(long memoryBytes, int fileDescriptors) {
		if (!tasks.isEmpty() || exclusiveFloorLease != null) {
			return null;
		}
		long retainedMemory = 0L;
		int retainedFileDescriptors = 0;
		for (ResourceLease retained : resourceLeases) {
			// Persistent sorter producer buffers are coordinator-owned, unbound allocations. A cursor or a lease
			// connected to another resource scope must be drained through its owner before a floor can be admitted.
			if (retained.state.get() != 0 || retained.bindingContext != null || retained.parentContext != null) {
				return null;
			}
			retainedMemory = Math.addExact(retainedMemory, retained.accountedMemoryBytes);
			retainedFileDescriptors = Math.addExact(retainedFileDescriptors, retained.accountedFileDescriptors);
		}
		if (retainedMemory != reservedMemoryBytes || retainedFileDescriptors != reservedFileDescriptors
				|| fileDescriptors > fileDescriptorLimit - reservedFileDescriptors) {
			return null;
		}
		long effectiveMemory = Math.addExact(reservedMemoryBytes, memoryBytes);
		reservedMemoryBytes = effectiveMemory;
		reservedFileDescriptors += fileDescriptors;
		peakReservedMemoryBytes.accumulateAndGet(reservedMemoryBytes, Math::max);
		peakReservedFileDescriptors.accumulateAndGet(reservedFileDescriptors, Math::max);
		recordEffectiveMemoryMinimum(effectiveMemory, "merge including retained producer storage");
		ResourceLease lease = new ResourceLease(this, memoryBytes, fileDescriptors, memoryBytes, fileDescriptors, null,
				true);
		resourceLeases.add(lease);
		exclusiveFloorLease = lease;
		return lease;
	}

	/** Promotes the declared, live cursor lease into an exclusive over-budget leaf envelope. */
	private ResourceLease reserveExclusiveMemoryFloor(ResourceLease cursorLease, long totalMemoryBytes,
			int totalFileDescriptors) throws IOException {
		if (cursorLease == null || cursorLease.owner != this) {
			throw new IOException("exclusive memory floor requires a declared cursor lease from this scheduler");
		}
		if (totalMemoryBytes <= memoryLimitBytes || totalFileDescriptors > fileDescriptorLimit) {
			throw new IOException("declared cursor lease floor must exceed the memory budget and fit the file limit");
		}
		synchronized (stateLock) {
			while (true) {
				if (!accepting || firstFailure != null) {
					throw new IOException("bulk task scheduler is stopping", firstFailure);
				}
				if (cursorLease.state.get() != 0 && cursorLease.state.get() != 3) {
					throw new IOException("declared cursor lease is not coordinator-owned");
				}
				if (!resourceLeases.contains(cursorLease)) {
					throw new IOException("declared cursor lease is not reserved by this scheduler");
				}
				boolean cursorOwnsFloor = cursorLease.exclusiveFloor && exclusiveFloorLease == cursorLease;
				if (!tasks.isEmpty() || exclusiveFloorLease != null && !cursorOwnsFloor) {
					try {
						stateLock.wait();
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						InterruptedIOException interrupted = new InterruptedIOException(
								"interrupted while waiting to promote the cursor lease");
						interrupted.initCause(e);
						throw interrupted;
					}
					continue;
				}
				if (resourceLeases.size() != 1 || !resourceLeases.contains(cursorLease)
						|| reservedMemoryBytes != cursorLease.accountedMemoryBytes
						|| reservedFileDescriptors != cursorLease.accountedFileDescriptors) {
					boolean retainedTaskLease = resourceLeases.stream()
							.anyMatch(lease -> lease != cursorLease && lease.state.get() == 1);
					if (retainedTaskLease) {
						try {
							stateLock.wait();
						} catch (InterruptedException e) {
							Thread.currentThread().interrupt();
							InterruptedIOException interrupted = new InterruptedIOException(
									"interrupted while waiting for retained adaptive work to release its lease");
							interrupted.initCause(e);
							throw interrupted;
						}
						continue;
					}
					throw new IOException("exclusive memory floor requires only the declared cursor lease");
				}
				if (totalMemoryBytes < cursorLease.memoryBytes
						|| totalFileDescriptors < cursorLease.fileDescriptors) {
					throw new IOException("exclusive memory floor is smaller than the declared cursor lease");
				}
				long additionalMemory = totalMemoryBytes - cursorLease.accountedMemoryBytes;
				int additionalFileDescriptors = totalFileDescriptors - cursorLease.accountedFileDescriptors;
				if (additionalMemory < 0 || additionalFileDescriptors < 0) {
					throw new IOException("exclusive memory floor does not cover the declared cursor lease");
				}
				reservedMemoryBytes = Math.addExact(reservedMemoryBytes, additionalMemory);
				reservedFileDescriptors = Math.addExact(reservedFileDescriptors, additionalFileDescriptors);
				peakReservedMemoryBytes.accumulateAndGet(reservedMemoryBytes, Math::max);
				peakReservedFileDescriptors.accumulateAndGet(reservedFileDescriptors, Math::max);
				recordEffectiveMemoryMinimum(totalMemoryBytes, "merge");
				ResourceLease lease = new ResourceLease(this, totalMemoryBytes, totalFileDescriptors,
						additionalMemory, additionalFileDescriptors, cursorLease.bindingContext, !cursorOwnsFloor);
				resourceLeases.add(lease);
				if (!cursorOwnsFloor) {
					exclusiveFloorLease = lease;
				}
				return lease;
			}
		}
	}

	private void recordEffectiveMemoryMinimum(long memoryBytes, String resourceKind) {
		long previousMinimum = effectiveMemoryMinimumBytes.getAndUpdate(previous -> Math.max(previous, memoryBytes));
		if (memoryBytes > previousMinimum) {
			System.getLogger(BulkTaskScheduler.class.getName())
					.log(System.Logger.Level.WARNING,
							"An LMDB bulk-load " + resourceKind
									+ " requires an exclusive minimum working-memory reservation of "
									+ memoryBytes + " bytes, above the configured budget of " + memoryLimitBytes
									+ " bytes");
		}
	}

	private Throwable firstFailure() {
		synchronized (stateLock) {
			return firstFailure;
		}
	}

	private void cancelBatch(List<? extends Future<?>> batch) {
		for (Future<?> future : batch) {
			future.cancel(true);
		}
	}

	private void awaitTasksUninterruptibly() {
		boolean interrupted = false;
		synchronized (stateLock) {
			while (!tasks.isEmpty()) {
				try {
					stateLock.wait();
				} catch (InterruptedException e) {
					interrupted = true;
				}
			}
		}
		if (interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	int peakActiveTasks() {
		return peakActiveTasks.get();
	}

	int peakQueuedTasks() {
		return peakQueuedTasks.get();
	}

	long reservedMemoryBytes() {
		synchronized (stateLock) {
			return reservedMemoryBytes;
		}
	}

	int reservedFileDescriptors() {
		synchronized (stateLock) {
			return reservedFileDescriptors;
		}
	}

	<T> void runAdaptive(AdaptiveWorkSource<T> source, AdaptiveCompletionConsumer<T> completionConsumer)
			throws IOException {
		Objects.requireNonNull(source, "source");
		Objects.requireNonNull(completionConsumer, "completionConsumer");
		if (CURRENT_SCHEDULER.get() == this) {
			throw new IllegalStateException("adaptive bulk work must be coordinated outside the scheduler pool");
		}

		int completionCapacity = maximumOutstandingTaskCount();
		LinkedBlockingQueue<AdaptiveFinished<T>> completions = new LinkedBlockingQueue<>(completionCapacity);
		Map<Long, AdaptiveTaskHandle<T>> outstanding = new HashMap<>(completionCapacity);
		boolean sourceFinished = false;
		AdaptiveWorkRequest<T> pendingRequest = null;
		try {
			while (!sourceFinished || pendingRequest != null || !outstanding.isEmpty()) {
				while (!sourceFinished && outstanding.size() < completionCapacity) {
					Throwable schedulerFailure = firstFailure();
					if (schedulerFailure != null) {
						if (schedulerFailure instanceof CancellationException cancellation) {
							throw cancellation;
						}
						throw new IOException("bulk task scheduler failed", schedulerFailure);
					}
					boolean drainCompletion = false;
					if (pendingRequest == null) {
						AdaptiveWorkPoll<T> poll = Objects.requireNonNull(source.poll(),
								"adaptive source poll result");
						switch (poll.kind()) {
						case EXHAUSTED -> {
							sourceFinished = true;
							continue;
						}
						case WAIT -> {
							if (!outstanding.isEmpty()) {
								drainCompletion = true;
							} else {
								awaitAdaptiveSource(source);
								continue;
							}
						}
						case REQUEST -> pendingRequest = poll.request();
						}
					}
					if (drainCompletion) {
						break;
					}

					AdaptiveWorkRequest<T> request = pendingRequest;
					if (request.allowSerialMemoryFloor() && !outstanding.isEmpty()) {
						break;
					}
					ResourceLease lease = tryReserveAdaptiveRequest(request);
					if (lease == null && !outstanding.isEmpty()) {
						break;
					}
					if (lease == null) {
						lease = reserveAdaptiveRequestBlocking(request);
					}
					pendingRequest = null;
					// The source owns sequential cursors. It may pull one bounded chunk here, after both the
					// completion slot and atomic task lease have been admitted.
					AdaptivePreparedWork<T> prepared = prepareAdaptiveWork(request, lease);
					if (outstanding.containsKey(prepared.workId())) {
						IOException duplicate = new IOException(
								"adaptive work source returned a duplicate outstanding work ID: "
										+ prepared.workId());
						cleanupPrepared(prepared, duplicate);
						closeLeaseAfterFailure(lease, duplicate);
						throw duplicate;
					}

					AdaptiveExecution<T> execution = new AdaptiveExecution<>(request, prepared, completions);
					AtomicBoolean retainLeaseForCompletion = new AtomicBoolean();
					execution.setRetainLeaseFlag(retainLeaseForCompletion);
					ResourceLease taskLease = lease;
					TrackedTask<Void> task;
					try {
						task = schedule(taskLease, () -> {
							execution.run(taskLease);
							return null;
						}, true, execution::finish, retainLeaseForCompletion);
					} catch (RuntimeException | Error failure) {
						finishPreparedAfterFailure(execution, failure);
						closeLeaseAfterFailure(lease, failure);
						Throwable underlyingFailure = firstFailure();
						if (underlyingFailure instanceof CancellationException cancellation) {
							throw cancellation;
						}
						if (underlyingFailure != null) {
							if (underlyingFailure != failure) {
								underlyingFailure.addSuppressed(failure);
							}
							throw new IOException("bulk task scheduler failed", underlyingFailure);
						}
						throw failure;
					}
					outstanding.put(prepared.workId(), new AdaptiveTaskHandle<>(task, execution, taskLease));
				}

				if (outstanding.isEmpty()) {
					continue;
				}

				AdaptiveFinished<T> finished;
				try {
					finished = completions.take();
				} catch (InterruptedException interrupted) {
					InterruptedIOException failure = new InterruptedIOException(
							"interrupted while waiting for adaptive bulk work");
					failure.initCause(interrupted);
					throw failure;
				}
				AdaptiveTaskHandle<T> handle = outstanding.get(finished.workId());
				if (handle == null) {
					throw new IOException("adaptive worker completed unknown work ID: " + finished.workId());
				}
				Throwable failure = firstFailure();
				if (failure == null) {
					failure = finished.failure();
				}
				if (failure != null) {
					if (failure instanceof CancellationException cancellation) {
						throw cancellation;
					}
					throw new IOException("adaptive bulk task failed", failure);
				}
				if (finished.result() == null) {
					throw new IOException("adaptive worker completed without a result");
				}
				Throwable consumerFailure = null;
				AdaptiveCompletion<T> completion = new AdaptiveCompletion<>(this, handle.resultLease(),
						finished.workId(), finished.stageEpoch(), finished.actualActivePartitions(),
						finished.result().committedWorkBytes(), finished.result().value());
				try {
					completionConsumer.accept(completion);
				} catch (Throwable failureDuringConsume) {
					consumerFailure = failureDuringConsume;
				}
				try {
					handle.consume(finished.result(), completion.resultOwnershipTransferred());
				} catch (Throwable cleanupFailure) {
					if (consumerFailure == null) {
						consumerFailure = cleanupFailure;
					} else if (consumerFailure != cleanupFailure) {
						consumerFailure.addSuppressed(cleanupFailure);
					}
				}
				if (consumerFailure != null) {
					if (consumerFailure instanceof IOException ioException) {
						throw ioException;
					}
					if (consumerFailure instanceof RuntimeException runtimeException) {
						throw runtimeException;
					}
					if (consumerFailure instanceof Error error) {
						throw error;
					}
					throw new IOException("adaptive completion consumer failed", consumerFailure);
				}
				try {
					handle.task().awaitCleanup();
				} catch (InterruptedException interrupted) {
					InterruptedIOException interruptedFailure = new InterruptedIOException(
							"interrupted while releasing adaptive bulk work");
					interruptedFailure.initCause(interrupted);
					throw interruptedFailure;
				}
				outstanding.remove(finished.workId());
			}
		} catch (Throwable failure) {
			boolean interrupted = cancelAndAwaitAdaptive(outstanding, completions, failure);
			if (failure instanceof InterruptedIOException || failure instanceof InterruptedException || interrupted) {
				Thread.currentThread().interrupt();
			}
			if (failure instanceof IOException ioException) {
				throw ioException;
			}
			if (failure instanceof RuntimeException runtimeException) {
				throw runtimeException;
			}
			if (failure instanceof Error error) {
				throw error;
			}
			throw new IOException("adaptive bulk-work coordination failed", failure);
		}
	}

	private ResourceLease tryReserveAdaptiveRequest(AdaptiveWorkRequest<?> request) throws IOException {
		if (request.exclusiveFloorBaseLease() != null) {
			if (request.memoryBytes() > memoryLimitBytes) {
				if (!request.allowSerialMemoryFloor()) {
					throw new IOException("bulk task reservation exceeds configured memory or file-descriptor limit");
				}
				return null;
			}
			return tryReserveAdaptiveBase(request.exclusiveFloorBaseLease(), request.memoryBytes(),
					request.fileDescriptors());
		}
		if (request.memoryBytes() > memoryLimitBytes) {
			if (!request.allowSerialMemoryFloor()) {
				throw new IOException("bulk task reservation exceeds configured memory or file-descriptor limit");
			}
			return null;
		}
		return tryReserve(request.memoryBytes(), request.fileDescriptors());
	}

	private ResourceLease reserveAdaptiveRequestBlocking(AdaptiveWorkRequest<?> request) throws IOException {
		if (request.exclusiveFloorBaseLease() != null) {
			return reserveAdaptiveBaseBlocking(request.exclusiveFloorBaseLease(), request.memoryBytes(),
					request.fileDescriptors(), request.allowSerialMemoryFloor());
		}
		return reserveForWork(new Work<>(request.memoryBytes(), request.fileDescriptors(), () -> null,
				request.allowSerialMemoryFloor()));
	}

	private static void awaitAdaptiveSource(AdaptiveWorkSource<?> source) throws IOException {
		try {
			source.awaitReady();
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			InterruptedIOException failure = new InterruptedIOException(
					"interrupted while waiting for adaptive source");
			failure.initCause(interrupted);
			throw failure;
		}
	}

	private <T> boolean cancelAndAwaitAdaptive(Map<Long, AdaptiveTaskHandle<T>> outstanding,
			LinkedBlockingQueue<AdaptiveFinished<T>> completions, Throwable primaryFailure) {
		for (AdaptiveTaskHandle<?> handle : outstanding.values()) {
			handle.task().cancel(true);
		}
		boolean interrupted = Thread.interrupted();
		for (AdaptiveTaskHandle<?> handle : outstanding.values()) {
			interrupted |= handle.task().awaitCleanupUninterruptibly();
		}
		for (AdaptiveTaskHandle<?> handle : outstanding.values()) {
			try {
				handle.discardUnconsumedCompletion();
			} catch (Throwable cleanupFailure) {
				if (cleanupFailure != primaryFailure) {
					primaryFailure.addSuppressed(cleanupFailure);
				}
			}
		}
		completions.clear();
		return interrupted;
	}

	private static void cleanupPrepared(AdaptivePreparedWork<?> prepared, Throwable failure) {
		try {
			prepared.cleanup().run();
		} catch (Throwable cleanupFailure) {
			failure.addSuppressed(cleanupFailure);
		}
	}

	private static void finishPreparedAfterFailure(AdaptiveExecution<?> execution, Throwable failure) {
		try {
			execution.finish();
		} catch (Throwable cleanupFailure) {
			failure.addSuppressed(cleanupFailure);
		}
	}

	private static void closeLeaseAfterFailure(ResourceLease lease, Throwable failure) {
		try {
			lease.close();
		} catch (Throwable cleanupFailure) {
			failure.addSuppressed(cleanupFailure);
		}
	}

	private <T> AdaptivePreparedWork<T> prepareAdaptiveWork(AdaptiveWorkRequest<T> request, ResourceLease lease)
			throws IOException {
		FileDescriptorScope scope;
		try {
			scope = bindResourceLease(lease);
		} catch (RuntimeException | Error bindingFailure) {
			closeLeaseAfterFailure(lease, bindingFailure);
			throw bindingFailure;
		}
		AdaptivePreparedWork<T> prepared = null;
		Throwable failure = null;
		try {
			prepared = request.preparation().prepare(lease);
			if (prepared == null) {
				failure = new IOException(
						"adaptive preparation returned null; transient readiness must use WAIT or EXHAUSTED from poll()");
				cleanupFailedPreparation(request.preparation(), lease, failure);
			}
		} catch (Exception | Error preparationFailure) {
			failure = preparationFailure;
			cleanupFailedPreparation(request.preparation(), lease, failure);
		}
		try {
			scope.close();
		} catch (RuntimeException | Error scopeFailure) {
			if (failure == null) {
				failure = scopeFailure;
				if (prepared != null) {
					cleanupPrepared(prepared, failure);
				}
				cleanupFailedPreparation(request.preparation(), lease, failure);
			} else if (failure != scopeFailure) {
				failure.addSuppressed(scopeFailure);
			}
			try {
				scope.close();
			} catch (RuntimeException | Error retryFailure) {
				if (failure != retryFailure) {
					failure.addSuppressed(retryFailure);
				}
			}
		}
		if (failure != null) {
			closeLeaseAfterFailure(lease, failure);
			if (failure instanceof IOException ioException) {
				throw ioException;
			}
			if (failure instanceof InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				InterruptedIOException interruptedFailure = new InterruptedIOException(
						"interrupted while preparing adaptive bulk work");
				interruptedFailure.initCause(interrupted);
				throw interruptedFailure;
			}
			if (failure instanceof RuntimeException runtimeException) {
				throw runtimeException;
			}
			if (failure instanceof Error error) {
				throw error;
			}
			throw new IOException("adaptive work preparation failed", failure);
		}
		return prepared;
	}

	private static void cleanupFailedPreparation(AdaptivePreparation<?> preparation, ResourceLease lease,
			Throwable failure) {
		try {
			preparation.cleanupAfterFailure(lease, failure);
		} catch (Throwable cleanupFailure) {
			failure.addSuppressed(cleanupFailure);
		}
	}

	long peakReservedMemoryBytes() {
		return peakReservedMemoryBytes.get();
	}

	long effectiveMemoryMinimumBytes() {
		return effectiveMemoryMinimumBytes.get();
	}

	int peakReservedFileDescriptors() {
		return peakReservedFileDescriptors.get();
	}

	private RejectedExecutionException rejected(String message, Throwable cause) {
		return cause == null ? new RejectedExecutionException(message)
				: new RejectedExecutionException(message, cause);
	}

	private void release(ResourceLease lease) {
		synchronized (stateLock) {
			reservedMemoryBytes -= lease.accountedMemoryBytes;
			reservedFileDescriptors -= lease.accountedFileDescriptors;
			resourceLeases.remove(lease);
			lease.bindingContext = null;
			if (exclusiveFloorLease == lease) {
				exclusiveFloorLease = null;
			}
			if (reservedMemoryBytes < 0 || reservedFileDescriptors < 0) {
				throw new IllegalStateException("bulk task resource reservations underflowed");
			}
			stateLock.notifyAll();
		}
	}

	private int availableFileDescriptors(FileDescriptorContext context) {
		int reserved = 0;
		int open = 0;
		for (FileDescriptorContext current = context; current != null; current = current.parent) {
			reserved = Math.addExact(reserved, current.reservedDescriptors);
			open = Math.addExact(open, current.openHandles.get());
		}
		return reserved - open;
	}

	private void queued() {
		int queued = queuedTasks.incrementAndGet();
		peakQueuedTasks.accumulateAndGet(queued, Math::max);
		if (queued > queuedTaskLimit) {
			throw new IllegalStateException("bulk task queue admission exceeded its bound");
		}
	}

	private void dequeued() {
		synchronized (stateLock) {
			int queued = queuedTasks.decrementAndGet();
			if (queued < 0) {
				throw new IllegalStateException("bulk task queue admission underflowed");
			}
			stateLock.notifyAll();
		}
	}

	private void taskFinished(TrackedTask<?> task) {
		// A queued Future can be canceled before an executor worker dequeues it. Remove its physical queue node before
		// releasing the logical queue slot, or another coordinator can observe the free slot and be rejected by the
		// still-full bounded executor queue.
		executor.remove(task);
		task.dequeue();
		task.releaseLeaseWhenNotTransferred();
		synchronized (stateLock) {
			tasks.remove(task);
			stateLock.notifyAll();
		}
	}

	private void taskFailed(TrackedTask<?> failedTask, Throwable failure) {
		List<TrackedTask<?>> cancel;
		synchronized (stateLock) {
			if (firstFailure != null) {
				return;
			}
			firstFailure = failure;
			accepting = false;
			cancel = new ArrayList<>(tasks);
			stateLock.notifyAll();
		}
		for (TrackedTask<?> task : cancel) {
			if (task != failedTask) {
				task.cancel(true);
			}
		}
	}

	private void taskStarted() {
		if (TASK_DEPTH.get() == 0) {
			int active = activeTasks.incrementAndGet();
			peakActiveTasks.accumulateAndGet(active, Math::max);
		}
		TASK_DEPTH.set(TASK_DEPTH.get() + 1);
	}

	private void taskExited() {
		int depth = TASK_DEPTH.get() - 1;
		TASK_DEPTH.set(depth);
		if (depth == 0) {
			activeTasks.decrementAndGet();
		}
	}

	@Override
	public void close() {
		if (CURRENT_SCHEDULER.get() == this) {
			throw new IllegalStateException("bulk task scheduler must be closed by its coordinator");
		}
		List<TrackedTask<?>> cancel;
		synchronized (stateLock) {
			accepting = false;
			cancel = new ArrayList<>(tasks);
			stateLock.notifyAll();
		}
		for (TrackedTask<?> task : cancel) {
			task.cancel(true);
		}
		executor.shutdownNow();
		boolean interrupted = false;
		while (!executor.isTerminated()) {
			try {
				executor.awaitTermination(1, TimeUnit.DAYS);
			} catch (InterruptedException e) {
				interrupted = true;
				executor.shutdownNow();
			}
		}
		if (interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	static final class ResourceLease implements AutoCloseable {
		private final BulkTaskScheduler owner;
		private final long memoryBytes;
		private volatile int fileDescriptors;
		private final long accountedMemoryBytes;
		private volatile int accountedFileDescriptors;
		private final FileDescriptorContext parentContext;
		private final boolean exclusiveFloor;
		private final AtomicInteger state = new AtomicInteger();
		private volatile FileDescriptorContext bindingContext;

		private ResourceLease(BulkTaskScheduler owner, long memoryBytes, int fileDescriptors) {
			this(owner, memoryBytes, fileDescriptors, memoryBytes, fileDescriptors, null, false);
		}

		private ResourceLease(BulkTaskScheduler owner, long memoryBytes, int fileDescriptors,
				long accountedMemoryBytes, int accountedFileDescriptors, FileDescriptorContext parentContext,
				boolean exclusiveFloor) {
			this.owner = owner;
			this.memoryBytes = memoryBytes;
			this.fileDescriptors = fileDescriptors;
			this.accountedMemoryBytes = accountedMemoryBytes;
			this.accountedFileDescriptors = accountedFileDescriptors;
			this.parentContext = parentContext;
			this.exclusiveFloor = exclusiveFloor;
		}

		long memoryBytes() {
			return memoryBytes;
		}

		int fileDescriptors() {
			return fileDescriptors;
		}

		private void ensureOpen() {
			if (state.get() != 0) {
				throw new IllegalStateException("resource lease is already submitted or closed");
			}
		}

		private void transferToTask() {
			synchronized (owner.stateLock) {
				if (!state.compareAndSet(0, 1)) {
					throw new IllegalStateException("resource lease is already submitted or closed");
				}
			}
		}

		private void acquireDescriptorBinding() {
			synchronized (owner.stateLock) {
				if (!state.compareAndSet(0, 3)) {
					throw new IllegalStateException("resource lease is already submitted, closed, or bound");
				}
			}
		}

		private void releaseDescriptorBinding() {
			synchronized (owner.stateLock) {
				if (!state.compareAndSet(3, 0)) {
					throw new IllegalStateException("resource lease descriptor binding is not active");
				}
				owner.stateLock.notifyAll();
			}
		}

		/**
		 * Releases closed cursor handles' descriptor capacity while retaining the cursor memory base for its leaves.
		 */
		void releaseFileDescriptors() {
			synchronized (owner.stateLock) {
				if (state.get() != 0) {
					throw new IllegalStateException(
							"cursor descriptor reservation cannot be released while its lease is bound");
				}
				int descriptors = accountedFileDescriptors;
				if (descriptors == 0) {
					return;
				}
				if (bindingContext != null && bindingContext.openHandles.get() != 0) {
					throw new IllegalStateException(
							"cursor descriptor reservation cannot be released with open handles");
				}
				accountedFileDescriptors = 0;
				fileDescriptors = 0;
				owner.reservedFileDescriptors -= descriptors;
				if (bindingContext != null) {
					bindingContext.reservedDescriptors -= descriptors;
				}
				if (owner.reservedFileDescriptors < 0 || bindingContext != null
						&& bindingContext.reservedDescriptors < 0) {
					throw new IllegalStateException("bulk scheduler file descriptor reservation underflowed");
				}
				owner.stateLock.notifyAll();
			}
		}

		private void releaseFromTask() {
			synchronized (owner.stateLock) {
				if (state.getAndSet(2) != 2) {
					owner.release(this);
				}
			}
		}

		@Override
		public void close() {
			synchronized (owner.stateLock) {
				if (state.get() == 3) {
					throw new IllegalStateException("resource lease is still bound to a file descriptor scope");
				}
				if (state.compareAndSet(0, 2)) {
					owner.release(this);
				}
			}
		}
	}

	static final class OpenFileHandle implements AutoCloseable {
		private final BulkTaskScheduler owner;
		private final FileDescriptorContext context;
		private final ResourceLease ownedLease;
		private final AtomicBoolean closed = new AtomicBoolean();

		private OpenFileHandle(BulkTaskScheduler owner, FileDescriptorContext context, ResourceLease ownedLease) {
			this.owner = owner;
			this.context = context;
			this.ownedLease = ownedLease;
		}

		private boolean isClosed() {
			return closed.get();
		}

		@Override
		public void close() {
			if (!closed.compareAndSet(false, true)) {
				return;
			}
			int local = context.openHandles.decrementAndGet();
			if (local < 0) {
				throw new IllegalStateException("bulk task file handle count underflowed");
			}
			synchronized (owner.stateLock) {
				int open = owner.openFileHandles.decrementAndGet();
				if (open < 0) {
					throw new IllegalStateException("bulk scheduler file handle count underflowed");
				}
				owner.stateLock.notifyAll();
			}
			if (ownedLease != null) {
				ownedLease.close();
			}
		}
	}

	static final class FileDescriptorScope implements AutoCloseable {
		private final BulkTaskScheduler owner;
		private final FileDescriptorContext previous;
		private final FileDescriptorContext installed;
		private final ResourceLease ownedLease;
		private final boolean restoreContext;
		private final ResourceLease boundLease;
		private final AtomicBoolean closed = new AtomicBoolean();

		private FileDescriptorScope(BulkTaskScheduler owner, FileDescriptorContext previous,
				FileDescriptorContext installed, ResourceLease ownedLease) {
			this(owner, previous, installed, ownedLease, ownedLease != null);
		}

		private FileDescriptorScope(BulkTaskScheduler owner, FileDescriptorContext previous,
				FileDescriptorContext installed, ResourceLease ownedLease, boolean restoreContext) {
			this(owner, previous, installed, ownedLease, restoreContext, null);
		}

		private FileDescriptorScope(BulkTaskScheduler owner, FileDescriptorContext previous,
				FileDescriptorContext installed, ResourceLease ownedLease, boolean restoreContext,
				ResourceLease boundLease) {
			this.owner = owner;
			this.previous = previous;
			this.installed = installed;
			this.ownedLease = ownedLease;
			this.restoreContext = restoreContext;
			this.boundLease = boundLease;
		}

		@Override
		public void close() {
			if (closed.get()) {
				return;
			}
			if (restoreContext) {
				if (CURRENT_FILE_DESCRIPTORS.get() != installed) {
					throw new IllegalStateException("bulk task file descriptor scopes closed out of order");
				}
				if (installed.openHandles.get() != 0) {
					throw new IllegalStateException("bulk file descriptor scope closed with open handles");
				}
			}
			if (!closed.compareAndSet(false, true)) {
				return;
			}
			if (restoreContext) {
				if (previous == null) {
					CURRENT_FILE_DESCRIPTORS.remove();
				} else {
					CURRENT_FILE_DESCRIPTORS.set(previous);
				}
			}
			if (ownedLease != null) {
				ownedLease.close();
			}
			if (boundLease != null) {
				boundLease.releaseDescriptorBinding();
			}
		}
	}

	/** A stream-lifetime claim within a task lease, or an owned atomic lease for coordinator-side streams. */
	static final class ResourceScope implements AutoCloseable {
		private final BulkTaskScheduler owner;
		private final FileDescriptorScope binding;
		private final ResourceLease ownedLease;
		private final FileDescriptorContext context;
		private final boolean requiresBoundContext;
		private final List<MemoryClaim> memoryClaims;
		private final AtomicBoolean closed = new AtomicBoolean();
		private OpenFileHandle fileHandle;

		private ResourceScope(BulkTaskScheduler owner, FileDescriptorScope binding, ResourceLease ownedLease,
				FileDescriptorContext context, boolean requiresBoundContext, List<MemoryClaim> memoryClaims) {
			this.owner = owner;
			this.binding = binding;
			this.ownedLease = ownedLease;
			this.context = context;
			this.requiresBoundContext = requiresBoundContext;
			this.memoryClaims = memoryClaims;
		}

		ResourceLease ownedLease() {
			return ownedLease;
		}

		boolean isExclusiveMemoryFloor() {
			return ownedLease != null && ownedLease.exclusiveFloor;
		}

		void trackHandle(OpenFileHandle handle) {
			Objects.requireNonNull(handle, "handle");
			if (fileHandle != null) {
				throw new IllegalStateException("bulk stream resource scope already tracks a file handle");
			}
			fileHandle = handle;
		}

		@Override
		public void close() {
			if (closed.get()) {
				return;
			}
			if (requiresBoundContext && CURRENT_FILE_DESCRIPTORS.get() != context) {
				throw new IllegalStateException("bulk stream resource scopes closed out of order");
			}
			if (fileHandle != null && !fileHandle.isClosed()) {
				throw new IllegalStateException("bulk stream resources closed with an open file handle");
			}
			if (!closed.compareAndSet(false, true)) {
				return;
			}
			owner.releaseMemoryClaims(memoryClaims);
			if (binding != null) {
				binding.close();
			}
			if (ownedLease != null) {
				ownedLease.close();
			}
		}
	}

	private static final class FileDescriptorContext {
		private final BulkTaskScheduler owner;
		private final long memoryBytes;
		private volatile int reservedDescriptors;
		private final FileDescriptorContext parent;
		private final AtomicInteger openHandles = new AtomicInteger();
		private final AtomicLong claimedMemoryBytes = new AtomicLong();

		private FileDescriptorContext(BulkTaskScheduler owner, long memoryBytes, int reservedDescriptors,
				FileDescriptorContext parent) {
			this.owner = owner;
			this.memoryBytes = memoryBytes;
			this.reservedDescriptors = reservedDescriptors;
			this.parent = parent;
		}
	}

