		private final int actualActivePartitions;
		private final long committedWorkBytes;
		private final T value;
		private final AtomicBoolean resultOwnershipTransferred = new AtomicBoolean();

		private AdaptiveCompletion(BulkTaskScheduler scheduler, ResourceLease resultLease, long workId, long stageEpoch,
				int actualActivePartitions, long committedWorkBytes, T value) {
			this.scheduler = Objects.requireNonNull(scheduler, "scheduler");
			this.resultLease = Objects.requireNonNull(resultLease, "resultLease");
			this.workId = workId;
			this.stageEpoch = stageEpoch;
			this.actualActivePartitions = actualActivePartitions;
			this.committedWorkBytes = committedWorkBytes;
			this.value = value;
		}

		long workId() {
			return workId;
		}

		long stageEpoch() {
			return stageEpoch;
		}

		int actualActivePartitions() {
			return actualActivePartitions;
		}

		long committedWorkBytes() {
			return committedWorkBytes;
		}

		T value() {
			return value;
		}

		void transferResultOwnership() {
			if (!resultOwnershipTransferred.compareAndSet(false, true)) {
				throw new IllegalStateException("adaptive result ownership was already transferred");
			}
		}

		FileDescriptorScope bindResultResources() throws IOException {
			return scheduler.bindRetainedResourceLease(resultLease);
		}

		private boolean resultOwnershipTransferred() {
			return resultOwnershipTransferred.get();
		}
